import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"43、【夬】 乾下兌上","description":"周易口訣義 - 43、【夬】 乾下兌上","frontmatter":{"title":"43、【夬】 乾下兌上","description":"周易口訣義 - 43、【夬】 乾下兌上"},"headers":[],"relativePath":"classics/koujueyi/045.md","filePath":"classics/koujueyi/045.md"}'),r={name:"classics/koujueyi/045.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_43、【夬】-乾下兌上" tabindex="-1">43、【夬】 乾下兌上 <a class="header-anchor" href="#_43、【夬】-乾下兌上" aria-label="Permalink to “43、【夬】 乾下兌上”">​</a></h1><p>彖曰：「夬」，決也，剛決柔也。健而說，決而和。「揚於王庭」，柔乘五剛也；「孚號有厲」，其危乃光也；「告自邑，不利即戎」，所尚乃窮也；「利有攸往」，剛長乃終也。</p><p>象曰：澤上於天，夬；君子以施祿及下，居德則忌。</p><p>初九，壯於前趾，往不勝為咎。</p><p>象曰：不勝而往，咎也。</p><p>九二，惕號，莫夜有戎，勿恤。</p><p>象曰：「有戎勿恤」，得中道也。</p><p>九三，壯於𬱓，有兇。君子夬夬獨行，遇雨若濡有慍，無咎。</p><p>象曰：「君子夬夬」，終無咎也。</p><p>九四，臀無膚，其行次且。牽羊悔亡，聞言不信。</p><p>象曰：「其行次且」，位不當也。「聞言不信」，聰不明也。</p><p>九五，莧陸夬夬，中行無咎。</p><p>象曰：「中行無咎」，中未光也。</p><p>上六，無號，終有兇。</p><p>象曰：「無號」之「兇」，終不可長也。</p><p>解讀</p><p>「夬揚於王庭」者，夬，決也。陽長至五，上六一柔而乘五剛，以人事喻，猶小人乘陵君子而為不順，眾共決之，故曰「夬」也。以剛決柔，以君子除小人，以剛正之德去邪謟，故可顯然於王者之庭，發揚決斷之事，示公正而無私隱，故曰「揚於王庭」。王庭亦公庭也。孚號有厲者，號，號令也；厲，危也。以剛正之德，而行孚信號令，施決斷之事，即上六之柔，亦喻邪謟小人，憂危之理，分明可見矣。「告自邑，不利即戎」者，夫興師動眾，必擾國亂人，今上六一柔，既乘剛不順，更喻小小之人要除，只可獨行決斷，不必更興師旅，故「不利即戎」也。「利有攸往」者，剛德既長，柔邪必消，剛道既成，利有所往也。象曰：「澤上於天，夬」者，澤性流動，雖蹔上天，必決而下，故取夬象。「君子以施祿及下，居德則忌」者，夫行決斷之道，必威恩並行，若威而不恩，即過在苛暴，若恩而不威，即失於制斷。君子行決之時，必須恩祿及於下人，又須居德於身，人則稟其威禁也，忌是禁也。</p><p>初九，壯於前趾，往不勝，為咎。趾，足也，處體最下。初九處決之首，欲行決斷之事，必須審其事宜，量其可否，然後始行其令。今為剛健之初，所壯在於趾足，剛壯未全，往必不勝，先有咎生，故曰「往不勝為咎」也。</p><p>「九二，惕號，莫夜有戎，勿恤」者，惕，懼。號，呼也。九二以剛處中，剛則正直，中又不偏，而有此德，能行決斷，雖有人懼呼來報雲：至莫必有戎寇侵害。緣九二自恃中直，不枉刑斷，雖聞此言，心無疑憂而惑，故曰「勿恤」也。</p><p>「九三，壯於𬱓，有兇，君子夬夬，獨行遇雨若濡，有慍，無咎」者，𬱓，面顴也，謂上六也。上六居眾陽之上，居而不安，若顴之處面。以九三剛陽而應上六，即是君子以助小人。𬱓之處面，誰人不見？故曰「壯於𬱓，有兇」也。剝卦以陰應陽為善，為陰柔須有所附。今九三以陽應陰，眾欲決去，獨往應之為兇。若達理君子，知小人不可與親，而能捨其本應，決之不疑，故曰「君子夬夬」也。若獨行殊志，應於小人，即有罪罰，如遇雨沾濡，徒懷忿恨，能無怨於人，即須「有慍無咎」也。</p><p>「九四：臀無膚，其行次且，牽羊悔亡，聞言不信」者，次且，行不前之貌也。羊，壯也。九四據下三陽，前進必見侵傷，猶如「臀無膚」，則居不得安，居不得安，行亦難進。然五陽當位，體又剛壯，四若牽繫於五，身有所託，即不剛，不敢侵傷，故曰「牽羊悔亡」也。然四亦是剛陽，雖五有剛壯，未肯信服事五，故曰「聞言不信也」。</p><p>「九五：莧陸夬夬，中行無咎」者，莧陸，草之柔脆，謂上六也。以九五之剛，決上六之柔，決之至易，如決柔脆之物，故曰「莧陸夬夬」。以居尊位而親決上六，即是以至尊而敵至卑，雖其克勝，不足為貴，但處位中行，才得免咎而已，故曰「中行無咎」也。</p><p>上六：無號，終有兇者，以柔乘剛而居眾陽之上，其猶小人乘陵君子，兇危必至，故戒之曰：「不用號啕，終致兇也。」</p>',23)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
